// (userId, appVersion) pairs already warned about in this page load: see warnIfAppNewerThanBridge.
const appVersionNotices = createAppVersionNoticeTracker();

/**
 * GM-tab notice when a player's phone app is NEWER than this bridge module, i.e. the GM has not updated
 * the module yet. An older app never warns (the bridge stays backward compatible with it). The app sends
 * its version as `meta.appVersion`; an old app sends none and is ignored. Shown once per (user, appVersion).
 */
export function warnIfAppNewerThanBridge(requester, appVersion) {
  if (!game.user?.isGM) return;
  const v = typeof appVersion === "string" ? appVersion.trim() : "";
  if (!appVersionNotices.shouldNotify(requester?.id, v, MODULE_VERSION)) return;
  ui.notifications?.warn(game.i18n.format(`${MODULE_ID}.compat.appNewerThanBridge`, {
    player: escapeNoticeText(requester.name),
    appVersion: escapeNoticeText(v),
    bridgeVersion: escapeNoticeText(MODULE_VERSION)
  }));
}



/**
 * The module used to be "foundry-mobile-bridge". If that copy is still active next to this one, both would
 * run a movement grid (double click-to-move) and mirror the same chat; tell the GM to disable it. The new
 * module keeps its grid off meanwhile (path-grid/embedded.js). Once per page load, GM only.
 */
let legacyModuleWarned = false;
export function warnIfLegacyModuleActive() {
  if (legacyModuleWarned || !game.user?.isGM) return;
  if (!game.modules.get(LEGACY_MODULE_ID)?.active) return;
  legacyModuleWarned = true;
  console.warn(`[${MODULE_ID}] The old "${LEGACY_MODULE_ID}" module is still active. Disable it: Bag of Worlds replaces it.`);
  ui.notifications?.warn(game.i18n.localize(`${MODULE_ID}.compat.legacyModuleActive`), { permanent: true });
}

